using HRIS.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace HRIS.Api.Controllers; [ApiController][Route("api/service-awards")][Authorize(Roles="HR,Support")] public class ServiceAwardsController:ControllerBase { private readonly IServiceAwardService _service; public ServiceAwardsController(IServiceAwardService service)=>_service=service; [HttpGet] public async Task<IActionResult> Get()=>Ok(await _service.GetAsync(User.ToUserContext())); [HttpPost("{id:int}/status")][Authorize(Roles="HR,Support")] public async Task<IActionResult> Status(int id,[FromQuery]string status){await _service.MarkStatusAsync(id,status,User.ToUserContext());return NoContent();} }
